<span class="line">        bookmarks<span class="token punctuation">.</span><span class="token function">map_get</span><span class="token punctuation">(</span><span class="token string">&quot;&quot;</span><span class="token punctuation">,</span> list_bookmarks<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
